/**
 * SpreadsheetML built-in PivotTable styles (PivotStyleLight1..28, Medium1..28,
 * Dark1..28) as differential formats per style element — not artwork.
 * Data adapted from Apache POI presetTableStyles.xml, Apache License 2.0:
 * https://github.com/apache/poi/blob/trunk/poi-ooxml/src/main/resources/org/apache/poi/xssf/usermodel/presetTableStyles.xml
 * https://www.apache.org/licenses/LICENSE-2.0
 * Theme/tint references stay semantic here (slot, tint) and resolve through the
 * workbook theme at paint time. Checked cell by cell against desktop Excel's
 * displayed formats for every style (2026-09-19).
 */
import { paletteById, normalizeHexColor } from "@mrnote/core/web/lib/spreadsheet/color-palette.ts";
import { tintSpreadsheetColor } from "@mrnote/core/web/lib/spreadsheet/theme-colors.ts";

type Color = string | readonly [number, number];
type Edge = "top" | "right" | "bottom" | "left";
type BorderStyle = "none" | "thin" | "medium" | "thick" | "double";
type Atom = {
  backgroundColor?: Color; color?: Color; bold?: boolean; italic?: boolean;
  border?: Partial<Record<Edge | "horizontal" | "vertical", { style: BorderStyle; color?: Color }>>;
};

export type PivotStyleCellPaint = {
  backgroundColor?: string;
  color?: string;
  bold?: boolean;
  italic?: boolean;
  /** `rank`: the precedence of the element that drew the edge, so a shared
   * edge between two cells goes to the higher-ranked side (as Excel draws it). */
  borderEdges?: Partial<Record<Edge, { style: Exclude<BorderStyle, "none">; color: string; rank: number }>>;
};

/** The style elements a PivotTable report cell can take, in Excel's precedence order. */
export type PivotStyleElement =
  | "wholeTable" | "pageFieldLabels" | "pageFieldValues"
  | "firstColumnStripe" | "secondColumnStripe" | "firstRowStripe" | "secondRowStripe"
  | "firstColumn" | "lastColumn"
  | "firstHeaderCell" | "headerRow"
  | "firstSubtotalColumn" | "secondSubtotalColumn" | "thirdSubtotalColumn"
  | "firstSubtotalRow" | "secondSubtotalRow" | "thirdSubtotalRow"
  | "firstColumnSubheading" | "secondColumnSubheading" | "thirdColumnSubheading"
  | "firstRowSubheading" | "secondRowSubheading" | "thirdRowSubheading"
  | "totalRow";

/** One report cell: which elements apply, and whether it sits on each edge of
 * the region each element covers (a border on an element's outer edge is only
 * drawn on that edge). */
export interface PivotStyleCellLook {
  elements: ReadonlyArray<{
    element: PivotStyleElement;
    top?: boolean; bottom?: boolean; left?: boolean; right?: boolean;
  }>;
}

type PaintedEdge = NonNullable<PivotStyleCellPaint["borderEdges"]>[Edge];

const BORDER_WEIGHT: Record<Exclude<BorderStyle, "none">, number> = { thin: 1, medium: 2, thick: 3, double: 3 };







export function pickPivotBorderEdge(own: PaintedEdge, facing: PaintedEdge): PaintedEdge {
  if (!own) return facing;
  if (!facing) return own;
  const weight = BORDER_WEIGHT[facing.style] - BORDER_WEIGHT[own.style];
  if (weight !== 0) return weight > 0 ? facing : own;
  return facing.rank > own.rank ? facing : own;
}

export function isBuiltInPivotStyle(name: string): boolean {
  return Object.prototype.hasOwnProperty.call(RECIPES, name);
}

/**
 * Paint one PivotTable report cell with a built-in style. Elements are applied
 * in Excel's precedence (whole table first, then stripes, columns, headers,
 * subtotals, subheadings, grand total), each later element overriding.
 */
export function builtInPivotCellPaint(
  name: string,
  accents: readonly string[],
  look: PivotStyleCellLook,
): PivotStyleCellPaint {
  const recipe = RECIPES[name];
  if (!recipe) return {};
  const office = paletteById("office");
  const resolve = (color: Color): string => {
    if (typeof color === "string") return color;
    const [slot, tint] = color;
    const base = slot === 0 ? "#ffffff" : slot === 1 ? "#000000"
      : slot === 2 ? office.light2 : slot === 3 ? office.dark2
      : normalizeHexColor(accents[slot - 4]) ?? office.accents[slot - 4] ?? "#000000";
    return tintSpreadsheetColor(base, tint);
  };
  const result: PivotStyleCellPaint = {};
  const ordered = [...look.elements].sort(
    (a, b) => PIVOT_ELEMENT_ORDER.indexOf(a.element) - PIVOT_ELEMENT_ORDER.indexOf(b.element),
  );
  for (const entry of ordered) {
    const id = recipe[entry.element];
    if (id === undefined) continue;
    const atom = ATOMS[id];
    const rank = PIVOT_ELEMENT_ORDER.indexOf(entry.element);
    if (atom.backgroundColor) result.backgroundColor = resolve(atom.backgroundColor);
    if (atom.color) result.color = resolve(atom.color);
    if (atom.bold !== undefined) result.bold = atom.bold;
    if (atom.italic !== undefined) result.italic = atom.italic;
    if (!atom.border) continue;
    const edges = {
      top: entry.top ? "top" : "horizontal",
      bottom: entry.bottom ? "bottom" : "horizontal",
      left: entry.left ? "left" : "vertical",
      right: entry.right ? "right" : "vertical",
    } as const;
    for (const edge of ["top", "right", "bottom", "left"] as const) {
      const border = atom.border[edges[edge]];
      if (!border) continue;
      result.borderEdges ??= {};
      if (border.style === "none") delete result.borderEdges[edge];
      else result.borderEdges[edge] = { style: border.style, color: border.color ? resolve(border.color) : "#000000", rank };
    }
  }
  return result;
}

